import{_ as i}from"./chunks/smart-groups-new.hrKzalJR.js";import{_ as r,c as o,o as a,ae as l}from"./chunks/framework.DMK_uHmU.js";const s="/help-center/assets/smart-groups-manage.DWAfrqQt.png",e="/help-center/assets/smart-groups-actions.czT-BDsG.png",b=JSON.parse('{"title":"Smart Groups Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Groups/group-management.md","filePath":"Administration/Manage/Groups/group-management.md"}'),n={name:"Administration/Manage/Groups/group-management.md"};function u(p,t,c,g,h,m){return a(),o("div",null,t[0]||(t[0]=[l('<h1 id="smart-groups-management-guide" tabindex="-1">Smart Groups Management Guide <a class="header-anchor" href="#smart-groups-management-guide" aria-label="Permalink to &quot;Smart Groups Management Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Smart Groups component provides a powerful interface for creating and managing dynamic user groups. Unlike static groups, Smart Groups can automatically include members based on specified criteria, making them ideal for role-based access control, content targeting, and organizational structure management.</p><h2 id="accessing-smart-groups" tabindex="-1">Accessing Smart Groups <a class="header-anchor" href="#accessing-smart-groups" aria-label="Permalink to &quot;Accessing Smart Groups&quot;">​</a></h2><p>The Smart Groups component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to <code>/groups/GroupListView</code> in the system. You&#39;ll typically find a link to this page in the user management section or administration menu.</p><h2 id="smart-groups-interface-overview" tabindex="-1">Smart Groups Interface Overview <a class="header-anchor" href="#smart-groups-interface-overview" aria-label="Permalink to &quot;Smart Groups Interface Overview&quot;">​</a></h2><p>The Smart Groups interface consists of these key components:</p><p><img src="'+s+'" alt="homepage"></p><ol><li><p><strong>Header Section</strong>: Contains the title &quot;Smart Groups&quot; with a brief description</p></li><li><p><strong>Action Buttons</strong>:</p><ul><li>Create new Smart Group</li><li>Refresh data</li><li>Clear filters</li><li>Export to Excel</li></ul></li><li><p><strong>Search Bar</strong>: Global search field for finding specific groups</p></li><li><p><strong>Data Table</strong>: Displays group information in a scrollable, sortable table</p></li><li><p><strong>Empty State</strong>: Information displayed when no groups match current filters</p></li></ol><h2 id="navigating-the-smart-groups-list" tabindex="-1">Navigating the Smart Groups List <a class="header-anchor" href="#navigating-the-smart-groups-list" aria-label="Permalink to &quot;Navigating the Smart Groups List&quot;">​</a></h2><h3 id="sorting-groups" tabindex="-1">Sorting Groups <a class="header-anchor" href="#sorting-groups" aria-label="Permalink to &quot;Sorting Groups&quot;">​</a></h3><p>To sort the Smart Groups list:</p><ol><li>Click on any sortable column header (Name, Description, Users)</li><li>Click again to toggle between ascending and descending order</li><li>Click a third time to remove sorting</li></ol><h3 id="filtering-groups" tabindex="-1">Filtering Groups <a class="header-anchor" href="#filtering-groups" aria-label="Permalink to &quot;Filtering Groups&quot;">​</a></h3><p>There are multiple ways to filter the Smart Groups list:</p><ol><li><p><strong>Global Search</strong>:</p><ul><li>Enter text in the search box in the top-left corner</li><li>The system will search across group name and description fields</li></ul></li><li><p><strong>Filter Indicator</strong>:</p><ul><li>When filters are active, the filter button turns blue</li><li>Click the &quot;Filter Slash&quot; button to clear all active filters</li></ul></li></ol><h3 id="quick-actions" tabindex="-1">Quick Actions <a class="header-anchor" href="#quick-actions" aria-label="Permalink to &quot;Quick Actions&quot;">​</a></h3><p>The interface provides quick action buttons in the top-right corner:</p><ol><li><strong>Refresh Data</strong>: Updates the list with the latest group information</li><li><strong>Clear Filters</strong>: Removes all active filters</li><li><strong>Export to Excel</strong>: Exports the current list view to a CSV file</li></ol><h2 id="smart-group-operations" tabindex="-1">Smart Group Operations <a class="header-anchor" href="#smart-group-operations" aria-label="Permalink to &quot;Smart Group Operations&quot;">​</a></h2><h3 id="creating-a-new-smart-group" tabindex="-1">Creating a New Smart Group <a class="header-anchor" href="#creating-a-new-smart-group" aria-label="Permalink to &quot;Creating a New Smart Group&quot;">​</a></h3><p>To create a new Smart Group:</p><p><img src="'+i+'" alt="homepage"></p><ol><li>Click the &quot;+ Smart Group&quot; button in the top-right corner</li><li>The Smart Group Dialog will open with empty fields</li><li>Configure the group settings: <ul><li>Group Name (required)</li><li>Group Description</li><li>Membership rules and conditions</li></ul></li><li>Click &quot;Save&quot; to create the Smart Group</li></ol><h3 id="viewing-group-members" tabindex="-1">Viewing Group Members <a class="header-anchor" href="#viewing-group-members" aria-label="Permalink to &quot;Viewing Group Members&quot;">​</a></h3><p>To see which users belong to a Smart Group:</p><p><img src="'+e+'" alt="homepage"></p><ol><li>Click the users icon (people) in the Actions column</li><li>The Group Members dialog will open</li><li>All users matching the group&#39;s criteria will be displayed</li><li>Close the dialog when finished</li></ol><h3 id="editing-smart-groups" tabindex="-1">Editing Smart Groups <a class="header-anchor" href="#editing-smart-groups" aria-label="Permalink to &quot;Editing Smart Groups&quot;">​</a></h3><p>To edit an existing Smart Group:</p><p><img src="'+e+'" alt="homepage"></p><ol><li>Click on the group name or the pencil icon in the Actions column</li><li>The Smart Group Dialog will open with the current settings</li><li>Make necessary changes</li><li>Click &quot;Save&quot; to update the Smart Group</li></ol><h3 id="deleting-smart-groups" tabindex="-1">Deleting Smart Groups <a class="header-anchor" href="#deleting-smart-groups" aria-label="Permalink to &quot;Deleting Smart Groups&quot;">​</a></h3><p>To delete a Smart Group:</p><p><img src="'+e+'" alt="homepage"></p><ol><li>Click the trash icon in the Actions column</li><li>A confirmation dialog will appear asking &quot;Are you sure you want to delete [group_name]?&quot;</li><li>Click &quot;Delete&quot; to confirm or &quot;Cancel&quot; to abort</li><li>A success notification will appear when deletion is complete</li></ol><h3 id="exporting-group-data" tabindex="-1">Exporting Group Data <a class="header-anchor" href="#exporting-group-data" aria-label="Permalink to &quot;Exporting Group Data&quot;">​</a></h3><p>To export the Smart Groups list to Excel:</p><ol><li>Click the &quot;Export to Excel&quot; button (external link icon)</li><li>Confirm the export in the dialog that appears</li><li>The browser will download a CSV file</li><li>The export includes all currently visible groups (respects active filters)</li></ol><h2 id="understanding-smart-group-information" tabindex="-1">Understanding Smart Group Information <a class="header-anchor" href="#understanding-smart-group-information" aria-label="Permalink to &quot;Understanding Smart Group Information&quot;">​</a></h2><p>The Smart Groups list displays the following information for each group:</p><ol><li><strong>Group Avatar</strong>: Displays group initials in a circular badge</li><li><strong>Name</strong>: The primary identifier for the group</li><li><strong>Description</strong>: Information about the group&#39;s purpose</li><li><strong>Users</strong>: Badge showing the number of users in the group</li><li><strong>Actions</strong>: Interactive buttons for viewing members, editing, and deleting</li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="smart-group-dialog" tabindex="-1">Smart Group Dialog <a class="header-anchor" href="#smart-group-dialog" aria-label="Permalink to &quot;Smart Group Dialog&quot;">​</a></h3><p>The Smart Group Dialog provides powerful tools for defining group membership:</p><ol><li><p><strong>Basic Information</strong>:</p><ul><li>Group name</li><li>Description</li><li>Visual indicators (colors, icons)</li></ul></li><li><p><strong>Membership Rules</strong>:</p><ul><li>Create complex query conditions</li><li>Combine multiple criteria with AND/OR logic</li><li>Preview membership results</li></ul></li><li><p><strong>Manual Adjustments</strong>:</p><ul><li>Force include specific users</li><li>Force exclude specific users</li><li>Override query results</li></ul></li></ol><h3 id="state-persistence" tabindex="-1">State Persistence <a class="header-anchor" href="#state-persistence" aria-label="Permalink to &quot;State Persistence&quot;">​</a></h3><p>The Smart Groups component saves your view preferences:</p><ul><li>Sort order</li><li>Visible columns</li><li>Scroll position</li></ul><p>These preferences are stored in the session, so they persist when you navigate away and return.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Smart Groups list is empty</p><ul><li>Check if filters are active (blue filter button indicates active filters)</li><li>Click the &quot;Clear Filters&quot; button to remove all filters</li><li>Refresh the data using the refresh button</li><li>Check for network connectivity issues</li></ul><p><strong>Issue</strong>: Cannot create or edit a Smart Group</p><ul><li>Ensure you have proper permissions (Admin, Content, or Manager roles)</li><li>Check that all required fields are completed</li><li>Verify network connectivity</li><li>Look for error messages in toast notifications</li></ul><p><strong>Issue</strong>: Group membership not updating</p><ul><li>Smart Group membership is calculated in real-time</li><li>User attributes may have changed</li><li>Click the refresh button to reload the latest data</li><li>Check if the group query conditions still match your expectations</li></ul><p><strong>Issue</strong>: Export not working</p><ul><li>Check browser download settings</li><li>Ensure you have proper permissions</li><li>Try with a smaller dataset by applying filters first</li></ul><p><strong>Issue</strong>: Delete operation fails</p><ul><li>The group may be referenced by other system components</li><li>Another administrator may be editing the group</li><li>Check error messages for specific details</li><li>Try refreshing the list before attempting to delete again</li></ul><p><strong>Issue</strong>: Cannot access Smart Groups feature</p><ul><li>Verify you have the required role (Admin, Content, or Manager)</li><li>Check if your access credentials are still valid</li><li>Ensure your browser supports all required features</li></ul><hr><p>For additional assistance with Smart Groups management, please contact your system administrator.</p>',67)]))}const G=r(n,[["render",u]]);export{b as __pageData,G as default};
